// Python-compatible output formatting for the bech32 port.
// Pure ESM, no dependencies, plain JS arrays/strings only.

// Faithful Python repr() for a string:
// - prefer single quotes
// - if the string contains a single quote but no double quote, use double quotes
// - otherwise escape single quotes (and keep single-quote delimiters)
// - escape backslash; escape \n \t \r; other non-printable chars as \xNN
export function pyReprStr(s) {
  let quote = "'";
  if (s.includes("'") && !s.includes('"')) {
    quote = '"';
  }
  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (code < 32 || code === 127) {
      out += '\\x' + code.toString(16).padStart(2, '0');
    } else {
      out += ch;
    }
  }
  out += quote;
  return out;
}

// Format the decoder result exactly as Python's print() would print the
// (hrp, data) tuple: "(None, None)" for null, otherwise
// "(<repr of hrp>, [<ints>])".
export function formatResult(result) {
  if (result === null || result === undefined) {
    return '(None, None)';
  }
  const items = result.data.map((n) => String(n)).join(', ');
  return '(' + pyReprStr(result.hrp) + ', [' + items + '])';
}

