// Bech32 decoding (classic const-1 checksum only), ported from the PyPI
// `bech32` package semantics. Pure JS, ES Modules, plain arrays/numbers/strings.

export const CHARSET = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l';

const GENERATORS = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];

// Internal: 5-bit value for a character, or -1 if not in the charset.
function charsetRev(c) {
  return CHARSET.indexOf(c);
}

export function hrpExpand(hrp) {
  const ret = [];
  for (let i = 0; i < hrp.length; i++) ret.push(hrp.charCodeAt(i) >> 5);
  ret.push(0);
  for (let i = 0; i < hrp.length; i++) ret.push(hrp.charCodeAt(i) & 31);
  return ret;
}

export function polymod(values) {
  let chk = 1;
  for (const v of values) {
    const top = chk >> 25;
    chk = ((chk & 0x1ffffff) << 5) ^ v;
    for (let i = 0; i < 5; i++) {
      if ((top >> i) & 1) chk ^= GENERATORS[i];
    }
  }
  return chk;
}

// spec: classic Bech32 (const 1) only; bech32m checksums are rejected.
export function verifyChecksum(hrp, data) {
  return polymod(hrpExpand(hrp).concat(data)) === 1;
}

// Returns { hrp, data } with the 6 checksum values removed, or null if invalid.
export function bech32Decode(str) {
  if (typeof str !== 'string') return null;
  for (let i = 0; i < str.length; i++) {
    const ord = str.charCodeAt(i);
    if (ord < 33 || ord > 126) return null;
  }
  if (str.toLowerCase() !== str && str.toUpperCase() !== str) return null;
  const bech = str.toLowerCase();
  const pos = bech.lastIndexOf('1');
  if (pos < 1 || pos + 7 > bech.length || bech.length > 90) return null;
  const hrp = bech.slice(0, pos);
  const data = [];
  for (let i = pos + 1; i < bech.length; i++) {
    const v = charsetRev(bech[i]);
    if (v === -1) return null;
    data.push(v);
  }
  if (!verifyChecksum(hrp, data)) return null;
  return { hrp: hrp, data: data.slice(0, data.length - 6) };
}

