// Minimal argparse emulation for: parser.add_argument('--a', type=str, required=True)

function usage(prog) {
  return 'usage: ' + prog + ' [-h] --a A';
}

function printHelp(prog) {
  process.stdout.write(
    usage(prog) +
      '\n\noptions:\n' +
      '  -h, --help  show this help message and exit\n' +
      '  --a A\n'
  );
}

function fail(prog, msg) {
  process.stderr.write(usage(prog) + '\n' + prog + ': error: ' + msg + '\n');
  process.exit(2);
}

export function parseArgs(argv) {
  const parts = String(argv[1] || '').split('/');
  const prog = parts[parts.length - 1];
  const args = argv.slice(2);

  if (args.includes('-h') || args.includes('--help')) {
    printHelp(prog);
    process.exit(0);
  }

  let a = null;
  let seen = false;
  const unknown = [];

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--a') {
      seen = true;
      if (i + 1 >= args.length) {
        fail(prog, 'argument --a: expected one argument');
      }
      a = args[++i];
    } else if (arg.startsWith('--a=')) {
      seen = true;
      a = arg.slice(4);
    } else {
      unknown.push(arg);
    }
  }

  if (!seen) {
    fail(prog, 'the following arguments are required: --a');
  }
  if (unknown.length > 0) {
    fail(prog, 'unrecognized arguments: ' + unknown.join(' '));
  }

  return { a };
}

